import { useCallback, useEffect, useRef, useState, type FormEvent } from 'react';
import {
  approveStageMeasurementTemplate, cancelProductionOrder, completeProductionOrder, completeProductionStage,
  createProductionOrder, createStageMeasurementTemplate,
  getProductionOrder, getProductionStage, issueProductionMaterial, issueProductionMaterials, listProductionLosses,
  listProductionOrders, listProductionStages, recordProductionMaterialDisposition, recordProductionOutput, recordStageMeasurements, releaseBatchQuality,
  releaseProductionMaterialReturn, releaseProductionOrder, requestProductionBatchAdjustment,
  resolveProductionRework, reviewProductionBatchAdjustment, returnProductionMaterial,
  startProductionStage,
  type ProductionLossWorkspace as LossData, type ProductionOrder, type ProductionOrderWorkspace as OrderData,
  type ProductionStage, type ProductionStageWorkspace as StageData,
} from '../api/manufacturingExecution';
import { StatusBadge } from './StatusBadge';
import {
  applyFailure, date, dateTime, Datum, decimal, Detail, DetailHead, emptyFeedback, Empty, Field,
  FormActions, LineTable, ManufacturingWorkspace, nullable, numeric, useManufacturingContextKey,
} from './ManufacturingWorkspaceShell';

export function ProductionOrderWorkspace() {
  const contextKey = useManufacturingContextKey(); const [workspace, setWorkspace] = useState<OrderData | null>(null);
  const [selected, setSelected] = useState<ProductionOrder | null>(null); const [editing, setEditing] = useState(false);
  const [form, setForm] = useState(blankOrder()); const [search, setSearch] = useState(''); const [status, setStatus] = useState('');
  const [sort, setSort] = useState('NEWEST'); const [page, setPage] = useState(1); const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false); const [feedback, setFeedback] = useState(emptyFeedback()); const key = useRef<string | null>(null);
  const [output, setOutput] = useState({ event_type: 'GOOD', quantity: '', reason_code: '', notes: '' });
  const [materialIssue, setMaterialIssue] = useState({ production_order_material_id: '', issue_kind: 'PLANNED', quantity: '', source_position_id: '', reason_code: '', notes: '' });
  const [materialReturn, setMaterialReturn] = useState({ production_material_posting_id: '', quantity: '', quarantine_position_id: '', reason_code: '', notes: '' });
  const [materialDisposition, setMaterialDisposition] = useState(blankMaterialDisposition());
  const [returnRelease, setReturnRelease] = useState({ posting_id: '', reusable_position_id: '' });
  const [adjustment, setAdjustment] = useState(blankAdjustment());
  const refresh = useCallback(async () => { setLoading(true); try { setWorkspace(await listProductionOrders({ q: search || undefined, status: status || undefined, sort, page })); } catch (error) { applyFailure(setFeedback, error, 'Unable to load production orders.'); } finally { setLoading(false); } }, [contextKey, search, status, sort, page]);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { setSelected(null); setEditing(false); setSearch(''); setStatus(''); setPage(1); setFeedback(emptyFeedback()); }, [contextKey]);
  useEffect(() => { key.current = null; }, [form]);
  async function choose(id: string) { setFeedback(emptyFeedback()); try { const row = await getProductionOrder(id); setSelected(row); setMaterialIssue((value) => ({ ...value, production_order_material_id: row.materials?.[0]?.id ?? '' })); setAdjustment(blankAdjustment(row.uom_code)); setEditing(false); } catch (error) { applyFailure(setFeedback, error, 'Unable to load production-order detail.'); } }
  function startNew() { setSelected(null); setForm(blankOrder()); setEditing(true); setFeedback(emptyFeedback()); }
  function chooseLine(id: string) { const line = workspace?.lookups.schedule_lines.find((item) => item.id === id); setForm((value) => ({ ...value, production_schedule_line_id: id, planned_start_date: line?.planned_start_date ?? '', planned_end_date: line?.planned_end_date ?? '' })); }
  async function save(event: FormEvent) {
    event.preventDefault(); const fields: Record<string, string> = {};
    if (!form.order_number.trim()) fields.order_number = 'Order number is required.';
    if (!form.batch_number.trim()) fields.batch_number = 'Batch number is required.';
    if (!form.production_schedule_line_id) fields.production_schedule_line_id = 'Choose a released schedule line.';
    if (Object.keys(fields).length) { setFeedback({ error: 'Correct the highlighted order fields.', success: null, fields }); return; }
    setBusy(true); try { key.current ??= crypto.randomUUID(); const result = await createProductionOrder({ order_number: form.order_number.trim().toUpperCase(), batch_number: form.batch_number.trim().toUpperCase(), production_schedule_line_id: form.production_schedule_line_id, planned_start_date: form.planned_start_date || null, planned_end_date: form.planned_end_date || null, shift_code: nullable(form.shift_code), notes: nullable(form.notes) }, key.current); key.current = null; await refresh(); setSelected(await getProductionOrder(result.id)); setEditing(false); setFeedback({ error: null, success: 'Draft production order created from the released schedule.', fields: {} }); } catch (error) { applyFailure(setFeedback, error, 'Unable to create the production order.'); } finally { setBusy(false); }
  }
  async function command(action: 'RELEASE' | 'ISSUE_MATERIALS' | 'COMPLETE' | 'CANCEL' | 'QUALITY_RELEASE') {
    if (!selected) return; const reason = action === 'CANCEL' ? window.prompt('Cancellation reason') : null; if (action === 'CANCEL' && !reason?.trim()) return;
    setBusy(true); try {
      if (action === 'RELEASE') await releaseProductionOrder(selected, crypto.randomUUID());
      else if (action === 'ISSUE_MATERIALS') await issueProductionMaterials(selected, crypto.randomUUID());
      else if (action === 'COMPLETE') await completeProductionOrder(selected, crypto.randomUUID());
      else if (action === 'QUALITY_RELEASE') await releaseBatchQuality(selected, crypto.randomUUID());
      else await cancelProductionOrder(selected, reason!.trim(), crypto.randomUUID());
      await refresh(); setSelected(await getProductionOrder(selected.id));
      setFeedback({ error: null, success: ({ RELEASE: 'Production order released.', ISSUE_MATERIALS: 'Reserved material issued by FEFO.', COMPLETE: 'Production order completed.', CANCEL: 'Production order cancelled.', QUALITY_RELEASE: 'Batch quality released.' })[action], fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to complete the production command.'); } finally { setBusy(false); }
  }
  async function recordOutput(event: FormEvent) {
    event.preventDefault();
    if (!selected || numeric(output.quantity) <= 0) { setFeedback({ error: 'Enter a positive output quantity.', success: null, fields: { output_quantity: 'Quantity must be greater than zero.' } }); return; }
    if (output.event_type !== 'GOOD' && !output.reason_code.trim()) { setFeedback({ error: 'A reason code is required for loss or rework.', success: null, fields: { output_reason: 'Enter a concise reason code.' } }); return; }
    setBusy(true); try {
      await recordProductionOutput(selected, { event_type: output.event_type, quantity: output.quantity, reason_code: output.event_type === 'GOOD' ? null : output.reason_code.trim().toUpperCase(), notes: nullable(output.notes) }, crypto.randomUUID());
      await refresh(); setSelected(await getProductionOrder(selected.id)); setOutput({ event_type: 'GOOD', quantity: '', reason_code: '', notes: '' });
      setFeedback({ error: null, success: 'Production output recorded and batch totals recalculated.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to record production output.'); } finally { setBusy(false); }
  }
  async function postMaterialIssue(event: FormEvent) {
    event.preventDefault();
    if (!selected || !materialIssue.production_order_material_id || numeric(materialIssue.quantity) <= 0) { setFeedback({ error: 'Choose a material and enter a positive issue quantity.', success: null, fields: { material_issue_quantity: 'Quantity must be greater than zero.' } }); return; }
    if (materialIssue.issue_kind === 'ADDITIONAL' && (!materialIssue.source_position_id || !materialIssue.reason_code.trim())) { setFeedback({ error: 'Additional issues require a stock position and reason.', success: null, fields: { material_issue_reason: 'Reason and source stock are required.' } }); return; }
    setBusy(true); try {
      await issueProductionMaterial(selected, { production_order_material_id: materialIssue.production_order_material_id, issue_kind: materialIssue.issue_kind, quantity: materialIssue.quantity, source_position_id: materialIssue.source_position_id || null, reason_code: materialIssue.reason_code.trim().toUpperCase() || null, notes: nullable(materialIssue.notes) }, crypto.randomUUID());
      await refresh(); const row = await getProductionOrder(selected.id); setSelected(row); setMaterialIssue({ production_order_material_id: row.materials?.[0]?.id ?? '', issue_kind: 'PLANNED', quantity: '', source_position_id: '', reason_code: '', notes: '' });
      setFeedback({ error: null, success: 'Material issue posted once to inventory and reconciliation.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to post the material issue.'); } finally { setBusy(false); }
  }
  async function postMaterialReturn(event: FormEvent) {
    event.preventDefault();
    if (!selected || !materialReturn.production_material_posting_id || numeric(materialReturn.quantity) <= 0 || !materialReturn.quarantine_position_id || !materialReturn.reason_code.trim()) { setFeedback({ error: 'Choose an issued lot, matching quarantine position, quantity and reason.', success: null, fields: { material_return: 'All return controls are required.' } }); return; }
    setBusy(true); try {
      await returnProductionMaterial(selected, { production_material_posting_id: materialReturn.production_material_posting_id, quantity: materialReturn.quantity, quarantine_position_id: materialReturn.quarantine_position_id, reason_code: materialReturn.reason_code.trim().toUpperCase(), notes: nullable(materialReturn.notes) }, crypto.randomUUID());
      await refresh(); setSelected(await getProductionOrder(selected.id)); setMaterialReturn({ production_material_posting_id: '', quantity: '', quarantine_position_id: '', reason_code: '', notes: '' });
      setFeedback({ error: null, success: 'Return moved to quality quarantine with its original lot and owner.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to post the material return.'); } finally { setBusy(false); }
  }
  async function postMaterialDisposition(event: FormEvent) {
    event.preventDefault();
    if (!selected || !materialDisposition.parent_posting_id || numeric(materialDisposition.quantity) <= 0 || !materialDisposition.reason_code.trim() || !materialDisposition.disposition_code.trim()) { setFeedback({ error: 'Choose a source posting and complete the WIP disposition.', success: null, fields: { material_disposition: 'Source, quantity, reason and disposition are required.' } }); return; }
    setBusy(true); try {
      await recordProductionMaterialDisposition(selected, { parent_posting_id: materialDisposition.parent_posting_id, disposition_kind: materialDisposition.disposition_kind, quantity: materialDisposition.quantity, reason_code: materialDisposition.reason_code.trim().toUpperCase(), disposition_code: materialDisposition.disposition_code.trim().toUpperCase(), notes: nullable(materialDisposition.notes) }, crypto.randomUUID());
      await refresh(); setSelected(await getProductionOrder(selected.id)); setMaterialDisposition(blankMaterialDisposition());
      setFeedback({ error: null, success: 'WIP waste or rework classified once without a second inventory deduction.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to post the material disposition.'); } finally { setBusy(false); }
  }
  async function approveMaterialReturn(postingId: string) {
    if (!selected || returnRelease.posting_id !== postingId || !returnRelease.reusable_position_id) { setFeedback({ error: 'Choose the matching reusable-stock position.', success: null, fields: {} }); return; }
    setBusy(true); try {
      await releaseProductionMaterialReturn(selected, postingId, { reusable_position_id: returnRelease.reusable_position_id, notes: 'Independent QC release to reusable inventory.' }, crypto.randomUUID());
      await refresh(); setSelected(await getProductionOrder(selected.id)); setReturnRelease({ posting_id: '', reusable_position_id: '' });
      setFeedback({ error: null, success: 'QC-approved return released to reusable inventory.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to release the returned material.'); } finally { setBusy(false); }
  }
  function changeAdjustmentType(adjustment_type: string) {
    const defaults = adjustment_type === 'MATERIAL'
      ? { metric_code: 'MATERIAL_NET_CONSUMPTION', subject_id: selected?.materials?.[0]?.id ?? '', uom_code: selected?.materials?.[0]?.uom_code ?? '' }
      : adjustment_type === 'STAGE_MEASUREMENT'
        ? { metric_code: 'STAGE_MEASUREMENT', subject_id: selected?.stages?.[0]?.id ?? '', uom_code: '' }
        : adjustment_type === 'COST'
          ? { metric_code: 'COST_VALUE', subject_id: selected?.cost_snapshots?.[0]?.id ?? '', uom_code: '' }
          : { metric_code: 'GOOD_OUTPUT', subject_id: '', uom_code: selected?.uom_code ?? '' };
    setAdjustment({ ...adjustment, adjustment_type, ...defaults, signed_quantity: '', signed_value: '' });
  }
  async function requestAdjustment(event: FormEvent) {
    event.preventDefault(); if (!selected) return;
    const amount = adjustment.adjustment_type === 'COST' ? adjustment.signed_value : adjustment.signed_quantity;
    if (!adjustment.adjustment_number.trim() || !adjustment.reason.trim() || !amount || numeric(amount) === 0
      || (adjustment.adjustment_type !== 'OUTPUT' && !adjustment.subject_id)
      || (adjustment.adjustment_type !== 'COST' && !adjustment.uom_code)) {
      setFeedback({ error: 'Complete the correction number, subject, signed amount, UOM and reason.', success: null, fields: { adjustment: 'A signed non-zero correction and evidence-based reason are required.' } }); return;
    }
    setBusy(true); try {
      await requestProductionBatchAdjustment(selected, { adjustment_number: adjustment.adjustment_number.trim().toUpperCase(), adjustment_type: adjustment.adjustment_type, reason: adjustment.reason.trim(), effects: [{ metric_code: adjustment.metric_code, subject_id: adjustment.adjustment_type === 'OUTPUT' ? null : adjustment.subject_id, signed_quantity: adjustment.adjustment_type === 'COST' ? '0' : adjustment.signed_quantity, uom_code: adjustment.adjustment_type === 'COST' ? null : adjustment.uom_code.toUpperCase(), signed_value: adjustment.adjustment_type === 'COST' ? adjustment.signed_value : '0', currency: adjustment.adjustment_type === 'COST' ? 'INR' : null }] }, crypto.randomUUID());
      await refresh(); const row = await getProductionOrder(selected.id); setSelected(row); setAdjustment(blankAdjustment(row.uom_code));
      setFeedback({ error: null, success: 'Closed-batch correction requested; original postings remain unchanged pending independent review.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to request the batch correction.'); } finally { setBusy(false); }
  }
  async function reviewAdjustment(id: string, decision: 'APPROVED' | 'REJECTED') {
    if (!selected) return; const row = selected.adjustments?.find((item) => item.id === id); if (!row) return;
    const notes = window.prompt(`${decision === 'APPROVED' ? 'Approval' : 'Rejection'} notes`); if (!notes?.trim()) return;
    setBusy(true); try {
      await reviewProductionBatchAdjustment(row, { decision, review_notes: notes.trim() }, crypto.randomUUID());
      await refresh(); setSelected(await getProductionOrder(selected.id));
      setFeedback({ error: null, success: `Correction ${decision.toLowerCase()} with an immutable approval effect.`, fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to review the batch correction.'); } finally { setBusy(false); }
  }
  const selectedIssueMaterial = selected?.materials?.find((line) => line.id === materialIssue.production_order_material_id);
  const issuePostings = selected?.materials?.flatMap((line) => (line.postings ?? []).filter((posting) => posting.posting_type === 'PLANNED_ISSUE' || posting.posting_type === 'ADDITIONAL_ISSUE').map((posting) => ({ line, posting }))) ?? [];
  const selectedReturnPosting = issuePostings.find(({ posting }) => posting.id === materialReturn.production_material_posting_id);
  const pendingReturns = selected?.materials?.flatMap((line) => (line.postings ?? []).filter((posting) => posting.posting_type === 'RETURN_QUARANTINE' && posting.status === 'QC_PENDING').map((posting) => ({ line, posting }))) ?? [];
  const reworkOutPostings = selected?.materials?.flatMap((line) => (line.postings ?? []).filter((posting) => posting.posting_type === 'REWORK_OUT').map((posting) => ({ line, posting }))) ?? [];
  const dispositionSources = materialDisposition.disposition_kind === 'REWORK_IN' ? reworkOutPostings : issuePostings;
  return <ManufacturingWorkspace code="PRO-ORDER" title="Production Orders" description="Turn released schedule lines into controlled batches, issue reserved material, and complete accountable output." notice="Orders preserve the released recipe and route snapshots; every stock issue, transition, and quality gate is server-authoritative." loading={loading} feedback={feedback} workspace={workspace} search={search} setSearch={setSearch} status={status} setStatus={setStatus} sort={sort} setSort={setSort} page={page} setPage={setPage} onNew={workspace?.allowed_actions.includes('CREATE') ? startNew : undefined} headings={['Order / batch', 'Output', 'Plan', 'Progress', 'Quality', 'Status']} rows={workspace?.data.map((row) => [<><b>{row.order_number}</b><small>{row.batch_number} · v{row.record_version}</small></>, <><b>{row.output_sku.code}</b><small>{row.output_sku.name}</small></>, `${decimal(row.planned_quantity)} ${row.uom_code}`, `${row.completed_stage_count}/${row.stage_count} stages`, <StatusBadge status={row.quality_status} />, <StatusBadge status={row.status} />]) ?? []} ids={workspace?.data.map((row) => row.id) ?? []} selectedId={selected?.id} onOpen={choose}>
    {editing ? <form className="requisition-form" onSubmit={save}><fieldset disabled={busy}><div className="requisition-field-grid"><label>Order number<input value={form.order_number} onChange={(e) => setForm({ ...form, order_number: e.target.value })} /><Field text={feedback.fields.order_number} /></label><label>Batch number<input value={form.batch_number} onChange={(e) => setForm({ ...form, batch_number: e.target.value })} /><Field text={feedback.fields.batch_number} /></label><label className="wide">Released schedule line<select aria-label="Released schedule line" value={form.production_schedule_line_id} onChange={(e) => chooseLine(e.target.value)}><option value="">Select scheduled output</option>{workspace?.lookups.schedule_lines.map((line) => <option key={line.id} value={line.id}>{line.schedule_number}/{line.line_number} · {line.output_sku.code} · {decimal(line.planned_quantity)} {line.uom_code}</option>)}</select><Field text={feedback.fields.production_schedule_line_id} /></label><label>Planned start<input type="date" value={form.planned_start_date} onChange={(e) => setForm({ ...form, planned_start_date: e.target.value })} /></label><label>Planned end<input type="date" value={form.planned_end_date} onChange={(e) => setForm({ ...form, planned_end_date: e.target.value })} /></label><label>Shift code<input aria-label="Production shift code" value={form.shift_code} onChange={(e) => setForm({ ...form, shift_code: e.target.value })} /></label><label className="wide">Notes<textarea rows={3} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></label></div><FormActions busy={busy} onClose={() => setEditing(false)} submit="Create production order" /></fieldset></form>
      : selected ? <Detail><DetailHead status={selected.status} version={selected.record_version} /><dl className="control-definition"><Datum text="Order / batch" value={`${selected.order_number} / ${selected.batch_number}`} /><Datum text="Schedule / shift" value={`${selected.schedule.number} · ${selected.shift_code ?? 'No shift'}`} /><Datum text="Output" value={`${selected.output_sku.code} · ${decimal(selected.planned_quantity)} ${selected.uom_code}`} /><Datum text="Recipe / route" value={`${selected.recipe.code} r${selected.recipe.revision} / ${selected.route.code}`} /><Datum text="Dates" value={`${date(selected.planned_start_date)} – ${date(selected.planned_end_date)}`} /><Datum text="Quality" value={<StatusBadge status={selected.quality_status} />} /><Datum text="Expected / final good" value={`${decimal(selected.expected_good_quantity ?? selected.planned_quantity)} / ${decimal(selected.final_good_quantity ?? selected.good_quantity)}`} /><Datum text="Output variance" value={`${decimal(selected.output_variance ?? '0')} (${selected.output_variance_percent === null ? selected.output_variance_exception ?? 'n/a' : `${decimal(selected.output_variance_percent ?? '0')}%`})`} /><Datum text="Plan / actual ingredient basis" value={selected.material_normalisation ? `${decimal(selected.material_normalisation.planned_quantity)} / ${decimal(selected.material_normalisation.actual_quantity)} · factor ${decimal(selected.material_normalisation.normalisation_factor)}${selected.material_normalisation.exception_code ? ` · ${selected.material_normalisation.exception_code}` : ''}` : 'Legacy standard'} /><Datum wide text="Notes" value={selected.notes ?? 'No notes'} /></dl>
        <h4>Ingredient and packaging reconciliation</h4><LineTable heads={['Material', 'Plan / normalised', 'Issued + additional − return', 'Waste / rework in / out', 'Adjusted net / efficiency variance', 'Lots']} rows={selected.materials?.map((line) => [<><b>{line.component_sku.code}</b><small>{line.component_sku.name}{line.is_packaging ? ' · packaging' : ''}</small></>, `${decimal(line.original_plan_quantity ?? line.required_quantity)} / ${decimal(line.normalised_standard_quantity ?? line.required_quantity)} ${line.uom_code}`, `${decimal(line.issued_quantity)} + ${decimal(line.additional_issued_quantity ?? '0')} − ${decimal(line.returned_quantity ?? '0')}`, `${decimal(line.wasted_quantity ?? '0')} / ${decimal(line.rework_in_quantity ?? '0')} / ${decimal(line.rework_out_quantity ?? '0')}`, <><b>{decimal(line.adjusted_net_consumed_quantity ?? line.net_consumed_quantity ?? line.issued_quantity)} / {decimal(line.adjusted_efficiency_variance ?? line.efficiency_variance ?? '0')}</b><small>posted {decimal(line.net_consumed_quantity ?? line.issued_quantity)} · approved Δ {decimal(line.approved_adjustment_quantity ?? '0')}</small></>, line.postings?.length ? line.postings.map((posting) => `${posting.lot_code}: ${posting.posting_type} ${decimal(posting.quantity)}`).join(', ') : 'Not posted']) ?? []} />
        {selected.allowed_actions.includes('ISSUE_MATERIAL') ? <form className="requisition-form manufacturing-command" onSubmit={postMaterialIssue}><fieldset disabled={busy}><h4>Post partial or additional issue</h4><div className="requisition-field-grid"><label>Material<select aria-label="Issue material line" value={materialIssue.production_order_material_id} onChange={(event) => setMaterialIssue({ ...materialIssue, production_order_material_id: event.target.value, source_position_id: '' })}><option value="">Select material</option>{selected.materials?.map((line) => <option key={line.id} value={line.id}>{line.component_sku.code} · remaining {decimal(Number(line.required_quantity) - Number(line.issued_quantity))} {line.uom_code}</option>)}</select></label><label>Issue kind<select aria-label="Material issue kind" value={materialIssue.issue_kind} onChange={(event) => setMaterialIssue({ ...materialIssue, issue_kind: event.target.value, source_position_id: '', reason_code: '' })}><option>PLANNED</option><option>ADDITIONAL</option></select></label><label>Quantity<input aria-label="Material issue quantity" type="number" min="0.000001" step="0.000001" value={materialIssue.quantity} onChange={(event) => setMaterialIssue({ ...materialIssue, quantity: event.target.value })} /><Field text={feedback.fields.material_issue_quantity} /></label>{materialIssue.issue_kind === 'ADDITIONAL' ? <><label className="wide">Source stock<select aria-label="Additional issue source position" value={materialIssue.source_position_id} onChange={(event) => setMaterialIssue({ ...materialIssue, source_position_id: event.target.value })}><option value="">Select reservable lot</option>{selectedIssueMaterial?.stock_positions?.filter((position) => position.is_reservable && numeric(position.available_quantity) > 0).map((position) => <option key={position.id} value={position.id}>{position.lot_code} · {position.location_code} · {decimal(position.available_quantity)} {position.uom_code}</option>)}</select></label><label>Reason code<input aria-label="Additional issue reason" value={materialIssue.reason_code} onChange={(event) => setMaterialIssue({ ...materialIssue, reason_code: event.target.value })} /><Field text={feedback.fields.material_issue_reason} /></label></> : null}<label className="wide">Issue notes<textarea rows={2} value={materialIssue.notes} onChange={(event) => setMaterialIssue({ ...materialIssue, notes: event.target.value })} /></label></div><div className="form-actions"><button className="primary" type="submit">Post material issue</button></div></fieldset></form> : null}
        {selected.allowed_actions.includes('RETURN_MATERIAL') ? <form className="requisition-form manufacturing-command" onSubmit={postMaterialReturn}><fieldset disabled={busy}><h4>Return issued material to QC quarantine</h4><div className="requisition-field-grid"><label className="wide">Issued lot posting<select aria-label="Return issue posting" value={materialReturn.production_material_posting_id} onChange={(event) => setMaterialReturn({ ...materialReturn, production_material_posting_id: event.target.value, quarantine_position_id: '' })}><option value="">Select issued lot</option>{issuePostings.map(({ line, posting }) => <option key={posting.id} value={posting.id}>{line.component_sku.code} · {posting.lot_code} · {decimal(posting.quantity)} {posting.uom_code}</option>)}</select></label><label>Return quantity<input aria-label="Material return quantity" type="number" min="0.000001" step="0.000001" value={materialReturn.quantity} onChange={(event) => setMaterialReturn({ ...materialReturn, quantity: event.target.value })} /></label><label className="wide">Quarantine position<select aria-label="Material return quarantine position" value={materialReturn.quarantine_position_id} onChange={(event) => setMaterialReturn({ ...materialReturn, quarantine_position_id: event.target.value })}><option value="">Select matching non-reservable position</option>{selectedReturnPosting?.line.stock_positions?.filter((position) => !position.is_reservable && position.lot_id === selectedReturnPosting.posting.lot_id && position.inventory_owner_id === selectedReturnPosting.posting.owner_id).map((position) => <option key={position.id} value={position.id}>{position.lot_code} · {position.location_code} · {position.quality_status}</option>)}</select></label><label>Reason code<input aria-label="Material return reason" value={materialReturn.reason_code} onChange={(event) => setMaterialReturn({ ...materialReturn, reason_code: event.target.value })} /></label><label className="wide">Return notes<textarea rows={2} value={materialReturn.notes} onChange={(event) => setMaterialReturn({ ...materialReturn, notes: event.target.value })} /></label><Field text={feedback.fields.material_return} /></div><div className="form-actions"><button className="primary" type="submit">Move return to quarantine</button></div></fieldset></form> : null}
        {selected.allowed_actions.includes('DISPOSE_MATERIAL') ? <form className="requisition-form manufacturing-command" onSubmit={postMaterialDisposition}><fieldset disabled={busy}><h4>Classify WIP material waste or rework</h4><div className="requisition-field-grid"><label>Posting type<select aria-label="Material disposition kind" value={materialDisposition.disposition_kind} onChange={(event) => setMaterialDisposition({ ...materialDisposition, disposition_kind: event.target.value, parent_posting_id: '' })}><option>WASTE</option><option>REWORK_OUT</option><option>REWORK_IN</option></select></label><label className="wide">Source posting<select aria-label="Material disposition source posting" value={materialDisposition.parent_posting_id} onChange={(event) => setMaterialDisposition({ ...materialDisposition, parent_posting_id: event.target.value })}><option value="">Select source ledger posting</option>{dispositionSources.map(({ line, posting }) => <option key={posting.id} value={posting.id}>{line.component_sku.code} · {posting.lot_code} · {posting.posting_type} {decimal(posting.quantity)} {posting.uom_code}</option>)}</select></label><label>Quantity<input aria-label="Material disposition quantity" type="number" min="0.000001" step="0.000001" value={materialDisposition.quantity} onChange={(event) => setMaterialDisposition({ ...materialDisposition, quantity: event.target.value })} /></label><label>Reason code<input aria-label="Material disposition reason" value={materialDisposition.reason_code} onChange={(event) => setMaterialDisposition({ ...materialDisposition, reason_code: event.target.value })} /></label><label>Disposition<input aria-label="Material disposition code" value={materialDisposition.disposition_code} onChange={(event) => setMaterialDisposition({ ...materialDisposition, disposition_code: event.target.value })} /></label><label className="wide">Notes<textarea rows={2} value={materialDisposition.notes} onChange={(event) => setMaterialDisposition({ ...materialDisposition, notes: event.target.value })} /></label><Field text={feedback.fields.material_disposition} /></div><div className="form-actions"><button className="primary" type="submit">Post WIP disposition</button></div></fieldset></form> : null}
        {selected.allowed_actions.includes('APPROVE_MATERIAL_RETURN') && pendingReturns.length ? <section className="manufacturing-command"><h4>Independent returned-material QC release</h4>{pendingReturns.map(({ line, posting }) => <div className="requisition-line-card" key={posting.id}><b>{line.component_sku.code} · {posting.lot_code}</b><small>{decimal(posting.quantity)} {posting.uom_code} awaiting QC disposition</small><label>Reusable position<select aria-label={`Reusable position for ${posting.lot_code}`} value={returnRelease.posting_id === posting.id ? returnRelease.reusable_position_id : ''} onChange={(event) => setReturnRelease({ posting_id: posting.id, reusable_position_id: event.target.value })}><option value="">Select matching released position</option>{line.stock_positions?.filter((position) => position.is_reservable && position.lot_id === posting.lot_id && position.inventory_owner_id === posting.owner_id).map((position) => <option key={position.id} value={position.id}>{position.location_code} · {position.quality_status}</option>)}</select></label><button className="secondary" type="button" disabled={busy || returnRelease.posting_id !== posting.id || !returnRelease.reusable_position_id} onClick={() => void approveMaterialReturn(posting.id)}>Approve for reuse</button></div>)}</section> : null}
        <h4>Route execution</h4><LineTable heads={['Seq', 'Operation', 'Work centre', 'Minutes', 'Status']} rows={selected.stages?.map((stage) => [String(stage.sequence_no), stage.operation_name, stage.work_center_code, stage.actual_minutes === null ? decimal(stage.planned_minutes) : `${decimal(stage.actual_minutes)} / ${decimal(stage.planned_minutes)}`, <StatusBadge status={stage.status} />]) ?? []} />
        {selected.allowed_actions.includes('RECORD_OUTPUT') ? <form className="requisition-form manufacturing-command" onSubmit={recordOutput}><fieldset disabled={busy}><h4>Record production output</h4><div className="requisition-field-grid"><label>Output type<select aria-label="Direct output type" value={output.event_type} onChange={(event) => setOutput({ ...output, event_type: event.target.value })}><option>GOOD</option><option>LOSS</option><option>REWORK</option></select></label><label>Quantity<input aria-label="Direct output quantity" type="number" min="0.000001" step="0.000001" value={output.quantity} onChange={(event) => setOutput({ ...output, quantity: event.target.value })} /><Field text={feedback.fields.output_quantity} /></label>{output.event_type !== 'GOOD' ? <label>Reason code<input aria-label="Direct output reason code" value={output.reason_code} onChange={(event) => setOutput({ ...output, reason_code: event.target.value })} /><Field text={feedback.fields.output_reason} /></label> : null}<label className="wide">Notes<textarea rows={2} value={output.notes} onChange={(event) => setOutput({ ...output, notes: event.target.value })} /></label></div><div className="form-actions"><button className="primary" type="submit">Record output</button></div></fieldset></form> : null}
        {selected.allowed_actions.includes('REQUEST_ADJUSTMENT') ? <form className="requisition-form manufacturing-command" onSubmit={requestAdjustment}><fieldset disabled={busy}><h4>Request audited closed-batch correction</h4><div className="requisition-field-grid"><label>Correction number<input aria-label="Correction number" value={adjustment.adjustment_number} onChange={(event) => setAdjustment({ ...adjustment, adjustment_number: event.target.value })} /></label><label>Correction type<select aria-label="Correction type" value={adjustment.adjustment_type} onChange={(event) => changeAdjustmentType(event.target.value)}><option>OUTPUT</option><option>MATERIAL</option><option>STAGE_MEASUREMENT</option><option>COST</option></select></label>{adjustment.adjustment_type === 'OUTPUT' ? <label>Output metric<select aria-label="Correction output metric" value={adjustment.metric_code} onChange={(event) => setAdjustment({ ...adjustment, metric_code: event.target.value })}><option>GOOD_OUTPUT</option><option>LOSS_OUTPUT</option><option>REWORK_OUTPUT</option></select></label> : null}{adjustment.adjustment_type === 'MATERIAL' ? <label className="wide">Material subject<select aria-label="Correction material subject" value={adjustment.subject_id} onChange={(event) => { const line = selected.materials?.find((item) => item.id === event.target.value); setAdjustment({ ...adjustment, subject_id: event.target.value, uom_code: line?.uom_code ?? '' }); }}><option value="">Select material</option>{selected.materials?.map((line) => <option key={line.id} value={line.id}>{line.component_sku.code} · posted {decimal(line.net_consumed_quantity ?? line.issued_quantity)} {line.uom_code}</option>)}</select></label> : null}{adjustment.adjustment_type === 'STAGE_MEASUREMENT' ? <label className="wide">Stage subject<select aria-label="Correction stage subject" value={adjustment.subject_id} onChange={(event) => setAdjustment({ ...adjustment, subject_id: event.target.value })}><option value="">Select stage</option>{selected.stages?.map((stage) => <option key={stage.id} value={stage.id}>{stage.sequence_no} · {stage.operation_name}</option>)}</select></label> : null}{adjustment.adjustment_type === 'COST' ? <label className="wide">Cost snapshot<select aria-label="Correction cost subject" value={adjustment.subject_id} onChange={(event) => setAdjustment({ ...adjustment, subject_id: event.target.value })}><option value="">Select finalized cost</option>{selected.cost_snapshots?.map((cost) => <option key={cost.id} value={cost.id}>{cost.cost_number} · snapshot {cost.snapshot_version} · INR {decimal(cost.actual_total_cost)}</option>)}</select></label> : null}<label>{adjustment.adjustment_type === 'COST' ? 'Signed value (INR)' : 'Signed quantity'}<input aria-label="Correction signed amount" type="number" step="0.000001" value={adjustment.adjustment_type === 'COST' ? adjustment.signed_value : adjustment.signed_quantity} onChange={(event) => setAdjustment(adjustment.adjustment_type === 'COST' ? { ...adjustment, signed_value: event.target.value } : { ...adjustment, signed_quantity: event.target.value })} /></label>{adjustment.adjustment_type !== 'COST' ? <label>UOM<input aria-label="Correction UOM" value={adjustment.uom_code} readOnly={adjustment.adjustment_type !== 'STAGE_MEASUREMENT'} onChange={(event) => setAdjustment({ ...adjustment, uom_code: event.target.value })} /></label> : null}<label className="wide">Evidence and reason<textarea aria-label="Correction reason" rows={3} value={adjustment.reason} onChange={(event) => setAdjustment({ ...adjustment, reason: event.target.value })} /><Field text={feedback.fields.adjustment} /></label></div><div className="form-actions"><button className="primary" type="submit">Submit for independent review</button></div></fieldset></form> : null}
        {selected.adjustments?.length ? <><h4>Correction and approval journal</h4><LineTable heads={['Correction / type', 'Proposed effect', 'Reason / requester', 'Status / review', 'Action']} rows={selected.adjustments.map((row) => [<><b>{row.adjustment_number}</b><small>{row.adjustment_type} · v{row.record_version}</small></>, row.proposed_effects.map((effect) => `${effect.metric_code}: ${effect.signed_quantity !== '0.000000' ? `${decimal(effect.signed_quantity)} ${effect.uom_code}` : `INR ${decimal(effect.signed_value)}`}`).join(', '), <><b>{row.reason}</b><small>{row.requested_by.name} · {dateTime(row.requested_at)}</small></>, <><StatusBadge status={row.status} /><small>{row.reviewed_by ? `${row.reviewed_by.name} · ${row.review_notes ?? ''}` : 'Independent review pending'}</small></>, row.allowed_actions.includes('REVIEW') ? <span className="table-actions"><button className="secondary compact-button" type="button" disabled={busy} onClick={() => void reviewAdjustment(row.id, 'APPROVED')}>Approve</button><button className="secondary compact-button" type="button" disabled={busy} onClick={() => void reviewAdjustment(row.id, 'REJECTED')}>Reject</button></span> : '—'])} /></> : null}
        <div className="form-actions">{selected.allowed_actions.filter((action) => ['RELEASE', 'ISSUE_MATERIALS', 'COMPLETE', 'CANCEL', 'QUALITY_RELEASE'].includes(action)).map((action) => <button key={action} className={action === 'RELEASE' || action === 'ISSUE_MATERIALS' || action === 'COMPLETE' || action === 'QUALITY_RELEASE' ? 'primary' : 'secondary'} disabled={busy} onClick={() => void command(action as Parameters<typeof command>[0])}>{orderActionLabel(action)}</button>)}</div></Detail>
      : <Empty text="Choose a production order or create one from a released schedule line." />}
  </ManufacturingWorkspace>;
}

export function ProductionStageWorkspace() {
  const contextKey = useManufacturingContextKey(); const [workspace, setWorkspace] = useState<StageData | null>(null); const [selected, setSelected] = useState<ProductionStage | null>(null);
  const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [sort, setSort] = useState('NEWEST'); const [page, setPage] = useState(1);
  const [actualMinutes, setActualMinutes] = useState(''); const [notes, setNotes] = useState(''); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [feedback, setFeedback] = useState(emptyFeedback());
  const [measurement, setMeasurement] = useState(blankMeasurement());
  const [template, setTemplate] = useState({ name: '', lines: [blankTemplateLine()] });
  const refresh = useCallback(async () => { setLoading(true); try { setWorkspace(await listProductionStages({ q: search || undefined, status: status || undefined, sort, page })); } catch (error) { applyFailure(setFeedback, error, 'Unable to load production stages.'); } finally { setLoading(false); } }, [contextKey, search, status, sort, page]);
  useEffect(() => { void refresh(); }, [refresh]); useEffect(() => { setSelected(null); setSearch(''); setStatus(''); setPage(1); setFeedback(emptyFeedback()); }, [contextKey]);
  async function choose(id: string) { setFeedback(emptyFeedback()); try { const row = await getProductionStage(id); setSelected(row); setActualMinutes(row.planned_minutes); setNotes(row.notes ?? ''); setMeasurement(blankMeasurement(row.measurement_template?.lines[0])); } catch (error) { applyFailure(setFeedback, error, 'Unable to load stage detail.'); } }
  async function command(action: 'START' | 'COMPLETE') {
    if (!selected) return; if (action === 'COMPLETE' && numeric(actualMinutes) < 0) { setFeedback({ error: 'Actual minutes cannot be negative.', success: null, fields: { actual_minutes: 'Enter zero or a positive duration.' } }); return; }
    setBusy(true); try { action === 'START' ? await startProductionStage(selected, crypto.randomUUID()) : await completeProductionStage(selected, { actual_minutes: actualMinutes, notes: nullable(notes) }, crypto.randomUUID()); await refresh(); const row = await getProductionStage(selected.id); setSelected(row); setActualMinutes(row.planned_minutes); setFeedback({ error: null, success: action === 'START' ? 'Stage started; an immutable start event was recorded.' : 'Stage completed with actual time.', fields: {} }); } catch (error) { applyFailure(setFeedback, error, 'Unable to complete the stage command.'); } finally { setBusy(false); }
  }
  async function recordMeasurement(event: FormEvent) {
    event.preventDefault(); if (!selected || numeric(measurement.quantity) < 0 || !measurement.measurement_source.trim() || !measurement.measurement_method.trim()) { setFeedback({ error: 'Complete the stage reading source, method and non-negative quantity.', success: null, fields: { measurement: 'Reading details are required.' } }); return; }
    setBusy(true); try {
      await recordStageMeasurements(selected.id, { measurements: [{ ...measurement, target_quantity: measurement.target_quantity || null, reason_code: nullable(measurement.reason_code)?.toUpperCase() ?? null, disposition_code: nullable(measurement.disposition_code)?.toUpperCase() ?? null, notes: nullable(measurement.notes) }] }, crypto.randomUUID());
      const row = await getProductionStage(selected.id); setSelected(row); setMeasurement(blankMeasurement(row.measurement_template?.lines[0])); setFeedback({ error: null, success: 'Immutable stage reading recorded and mass balance recalculated.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to record the stage measurement.'); } finally { setBusy(false); }
  }
  async function createTemplate(event: FormEvent) {
    event.preventDefault(); if (!selected || !template.name.trim() || template.lines.length === 0) return;
    setBusy(true); try {
      await createStageMeasurementTemplate(selected.id, { name: template.name.trim(), lines: template.lines.map((line) => ({ ...line, measurement_method: nullable(line.measurement_method) })) }, crypto.randomUUID());
      setSelected(await getProductionStage(selected.id)); setTemplate({ name: '', lines: [blankTemplateLine()] }); setFeedback({ error: null, success: 'Draft measurement template created; a different authorised user must approve it.', fields: {} });
    } catch (error) { applyFailure(setFeedback, error, 'Unable to create the stage measurement template.'); } finally { setBusy(false); }
  }
  async function approveTemplate(id: string) {
    if (!selected) return; setBusy(true); try { await approveStageMeasurementTemplate(id, crypto.randomUUID()); setSelected(await getProductionStage(selected.id)); setFeedback({ error: null, success: 'Measurement template independently approved and snapshotted to eligible pending stages.', fields: {} }); } catch (error) { applyFailure(setFeedback, error, 'Unable to approve the measurement template.'); } finally { setBusy(false); }
  }
  function patchTemplateLine(index: number, patch: Record<string, unknown>) { setTemplate((current) => ({ ...current, lines: current.lines.map((line, lineIndex) => lineIndex === index ? { ...line, ...patch } : line) })); }
  return <ManufacturingWorkspace code="PRO-STAGE" title="Stage Execution" description="Run route operations in sequence and capture time, physical readings, and count changes against each batch stage." notice="Approved measurement templates are snapshotted before a stage starts; measured and estimated readings remain distinguishable." loading={loading} feedback={feedback} workspace={workspace} search={search} setSearch={setSearch} status={status} setStatus={setStatus} sort={sort} setSort={setSort} page={page} setPage={setPage} headings={['Order / batch', 'Seq', 'Operation', 'Work centre', 'Minutes', 'Status']} rows={workspace?.data.map((row) => [<><b>{row.production_order.number}</b><small>{row.production_order.batch_number}</small></>, String(row.sequence_no), row.operation_name, row.work_center_code, row.actual_minutes === null ? decimal(row.planned_minutes) : `${decimal(row.actual_minutes)} / ${decimal(row.planned_minutes)}`, <StatusBadge status={row.status} />]) ?? []} ids={workspace?.data.map((row) => row.id) ?? []} selectedId={selected?.id} onOpen={choose}>
    {selected ? <Detail><DetailHead status={selected.status} version={selected.record_version} /><dl className="control-definition"><Datum text="Order" value={`${selected.production_order.number} / ${selected.production_order.batch_number}`} /><Datum text="Sequence" value={selected.sequence_no} /><Datum text="Operation" value={selected.operation_name} /><Datum text="Work centre" value={selected.work_center_code} /><Datum text="Planned minutes" value={decimal(selected.planned_minutes)} /><Datum text="Measurement template" value={selected.measurement_template ? `${selected.measurement_template.name} r${selected.measurement_template.revision}` : 'No approved template snapshot'} /><Datum text="Started" value={dateTime(selected.started_at)} /><Datum text="Completed" value={dateTime(selected.completed_at)} /><Datum wide text="Notes" value={selected.notes ?? 'No notes'} /></dl>
      {selected.allowed_actions.includes('CONFIGURE_MEASUREMENTS') ? <form className="requisition-form manufacturing-command" onSubmit={createTemplate}><fieldset disabled={busy}><h4>Propose stage measurement template</h4><div className="requisition-field-grid"><label className="wide">Template name<input aria-label="Measurement template name" value={template.name} onChange={(event) => setTemplate({ ...template, name: event.target.value })} /></label></div>{template.lines.map((line, index) => <div className="requisition-line-card" key={index}><div className="requisition-field-grid"><label>Reading kind<select aria-label={`Template reading kind ${index + 1}`} value={line.measurement_kind} onChange={(event) => patchTemplateLine(index, { measurement_kind: event.target.value })}>{workspace?.lookups.measurement_kinds?.map((kind) => <option key={kind}>{kind}</option>)}</select></label><label>Dimension<select aria-label={`Template dimension ${index + 1}`} value={line.quantity_dimension} onChange={(event) => patchTemplateLine(index, { quantity_dimension: event.target.value })}>{workspace?.lookups.quantity_dimensions?.map((dimension) => <option key={dimension}>{dimension}</option>)}</select></label><label>UOM<select aria-label={`Template UOM ${index + 1}`} value={line.uom_code} onChange={(event) => patchTemplateLine(index, { uom_code: event.target.value })}>{workspace?.lookups.uoms?.map((uom) => <option key={uom.code}>{uom.code}</option>)}</select></label><label>Default source<select aria-label={`Template value source ${index + 1}`} value={line.default_value_source} onChange={(event) => patchTemplateLine(index, { default_value_source: event.target.value })}>{workspace?.lookups.value_sources?.map((source) => <option key={source}>{source}</option>)}</select></label><label>Method<input aria-label={`Template method ${index + 1}`} value={line.measurement_method ?? ''} onChange={(event) => patchTemplateLine(index, { measurement_method: event.target.value })} /></label><label>Balance tolerance<input aria-label={`Template tolerance ${index + 1}`} type="number" min="0" step="0.000001" value={line.balance_tolerance} onChange={(event) => patchTemplateLine(index, { balance_tolerance: event.target.value })} /></label><label className="check-label"><input aria-label={`Template required ${index + 1}`} type="checkbox" checked={line.is_required} onChange={(event) => patchTemplateLine(index, { is_required: event.target.checked })} />Required before completion</label></div>{template.lines.length > 1 ? <button className="secondary compact-button" type="button" onClick={() => setTemplate({ ...template, lines: template.lines.filter((_, lineIndex) => lineIndex !== index) })}>Remove line</button> : null}</div>)}<div className="form-actions"><button className="secondary" type="button" onClick={() => setTemplate({ ...template, lines: [...template.lines, blankTemplateLine(workspace?.lookups.uoms?.[0]?.code)] })}>Add reading</button><button className="primary" type="submit">Create draft template</button></div></fieldset></form> : null}
      {selected.measurement_templates?.length ? <><h4>Template governance</h4><LineTable heads={['Revision', 'Template', 'Owner', 'Status', 'Action']} rows={selected.measurement_templates.map((row) => [String(row.revision), row.name, row.created_by?.name ?? '—', <StatusBadge status={row.status ?? 'DRAFT'} />, row.allowed_actions?.includes('APPROVE') ? <button className="secondary compact-button" disabled={busy} onClick={() => void approveTemplate(row.id)}>Approve independently</button> : '—'])} /></> : null}
      {selected.allowed_actions.includes('RECORD_MEASUREMENTS') ? <form className="requisition-form manufacturing-command" onSubmit={recordMeasurement}><fieldset disabled={busy}><h4>Record stage reading</h4><div className="requisition-field-grid"><label>Reading kind<select aria-label="Stage measurement kind" value={measurement.measurement_kind} onChange={(event) => setMeasurement({ ...measurement, measurement_kind: event.target.value })}>{workspace?.lookups.measurement_kinds?.map((kind) => <option key={kind}>{kind}</option>)}</select></label><label>Dimension<select aria-label="Stage measurement dimension" value={measurement.quantity_dimension} onChange={(event) => setMeasurement({ ...measurement, quantity_dimension: event.target.value })}>{workspace?.lookups.quantity_dimensions?.map((dimension) => <option key={dimension}>{dimension}</option>)}</select></label><label>Quantity<input aria-label="Stage measurement quantity" type="number" min="0" step="0.000001" value={measurement.quantity} onChange={(event) => setMeasurement({ ...measurement, quantity: event.target.value })} /></label><label>UOM<select aria-label="Stage measurement UOM" value={measurement.uom_code} onChange={(event) => setMeasurement({ ...measurement, uom_code: event.target.value })}>{workspace?.lookups.uoms?.map((uom) => <option key={uom.code}>{uom.code}</option>)}</select></label><label>Value source<select aria-label="Stage measurement value source" value={measurement.value_source} onChange={(event) => setMeasurement({ ...measurement, value_source: event.target.value })}>{workspace?.lookups.value_sources?.map((source) => <option key={source}>{source}</option>)}</select></label><label>Reading source<input aria-label="Stage measurement source" value={measurement.measurement_source} onChange={(event) => setMeasurement({ ...measurement, measurement_source: event.target.value })} /></label><label>Method<input aria-label="Stage measurement method" value={measurement.measurement_method} onChange={(event) => setMeasurement({ ...measurement, measurement_method: event.target.value })} /></label><label>Target quantity<input aria-label="Stage measurement target" type="number" min="0" step="0.000001" value={measurement.target_quantity} onChange={(event) => setMeasurement({ ...measurement, target_quantity: event.target.value })} /></label><label>Reason code<input aria-label="Stage measurement reason" value={measurement.reason_code} onChange={(event) => setMeasurement({ ...measurement, reason_code: event.target.value })} /></label><label>Disposition<input aria-label="Stage measurement disposition" value={measurement.disposition_code} onChange={(event) => setMeasurement({ ...measurement, disposition_code: event.target.value })} /></label><label className="wide">Notes<textarea rows={2} value={measurement.notes} onChange={(event) => setMeasurement({ ...measurement, notes: event.target.value })} /></label><Field text={feedback.fields.measurement} /></div><div className="form-actions"><button className="primary" type="submit">Record immutable reading</button></div></fieldset></form> : null}
      {selected.measurements?.length ? <><h4>Stage readings</h4><LineTable heads={['Seq', 'Kind / dimension', 'Quantity', 'Source / method', 'Operator', 'Recorded']} rows={selected.measurements.map((row) => [String(row.entry_sequence), <><b>{row.measurement_kind}</b><small>{row.quantity_dimension} · {row.value_source}</small></>, `${decimal(row.quantity)} ${row.uom_code}`, `${row.measurement_source} / ${row.measurement_method}`, row.operator.name, dateTime(row.recorded_at)])} /></> : null}
      {selected.mass_balance?.length ? <><h4>Mass and count balance</h4><LineTable heads={['Dimension / UOM', 'Inputs', 'Accounted outputs', 'Calculated unexplained', 'Recorded unexplained', 'Measured / estimated']} rows={selected.mass_balance.map((row) => [`${row.quantity_dimension} / ${row.uom_code}`, decimal(row.input_quantity), decimal(row.accounted_output_quantity), decimal(row.calculated_unexplained_quantity), decimal(row.recorded_unexplained_quantity), `${decimal(row.measured_quantity)} / ${decimal(row.estimated_quantity)}`])} /></> : null}
      {selected.measurement_adjustments?.length ? <><h4>Approved closed-batch reading corrections</h4><LineTable heads={['Correction', 'Signed quantity', 'Reason', 'Approved']} rows={selected.measurement_adjustments.map((row) => [row.adjustment_number, `${decimal(row.signed_quantity)} ${row.uom_code}`, row.reason, dateTime(row.approved_at)])} /></> : null}
      {selected.allowed_actions.includes('COMPLETE') ? <div className="requisition-field-grid inventory-command"><label>Actual minutes<input aria-label="Actual minutes" type="number" min="0" step="0.001" value={actualMinutes} onChange={(e) => setActualMinutes(e.target.value)} /><Field text={feedback.fields.actual_minutes} /></label><label className="wide">Completion note<textarea rows={3} value={notes} onChange={(e) => setNotes(e.target.value)} /></label></div> : null}<div className="form-actions">{selected.allowed_actions.includes('START') ? <button className="primary" disabled={busy} onClick={() => void command('START')}>Start stage</button> : null}{selected.allowed_actions.includes('COMPLETE') ? <button className="primary" disabled={busy} onClick={() => void command('COMPLETE')}>Complete stage</button> : null}</div></Detail> : <Empty text="Choose a route stage to start or complete." />}
  </ManufacturingWorkspace>;
}

export function ProductionLossWorkspace() {
  const contextKey = useManufacturingContextKey(); const [workspace, setWorkspace] = useState<LossData | null>(null); const [selected, setSelected] = useState<ProductionOrder | null>(null);
  const [form, setForm] = useState(blankOutputClassification()); const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [sort, setSort] = useState('NEWEST'); const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [feedback, setFeedback] = useState(emptyFeedback()); const key = useRef<string | null>(null);
  const refresh = useCallback(async (keepId?: string) => { setLoading(true); try { const data = await listProductionLosses({ q: search || undefined, status: status || undefined, sort, page }); setWorkspace(data); const id = keepId ?? selected?.id; if (id) setSelected(data.data.find((row) => row.id === id) ?? null); } catch (error) { applyFailure(setFeedback, error, 'Unable to load yield and loss records.'); } finally { setLoading(false); } }, [contextKey, search, status, sort, page, selected?.id]);
  useEffect(() => { void refresh(); }, [contextKey, search, status, sort, page]); useEffect(() => { setSelected(null); setSearch(''); setStatus(''); setPage(1); setFeedback(emptyFeedback()); }, [contextKey]); useEffect(() => { key.current = null; }, [form, selected?.record_version]);
  function choose(id: string) { setSelected(workspace?.data.find((row) => row.id === id) ?? null); setFeedback(emptyFeedback()); }
  async function record(event: FormEvent) {
    event.preventDefault(); if (!selected || numeric(form.quantity) <= 0) { setFeedback({ error: 'Enter a positive output quantity.', success: null, fields: { quantity: 'Quantity must be greater than zero.' } }); return; }
    if (form.event_type !== 'GOOD' && !form.reason_code.trim()) { setFeedback({ error: 'A reason code is required for loss or rework.', success: null, fields: { reason_code: 'Enter a concise reason code.' } }); return; }
    if (form.loss_category === 'REJECTED_OUTPUT' && !form.disposition_code.trim()) { setFeedback({ error: 'Rejected output requires a disposition.', success: null, fields: { disposition_code: 'Record the rejection disposition.' } }); return; }
    setBusy(true); try { key.current ??= crypto.randomUUID(); await recordProductionOutput(selected, { event_type: form.event_type, quantity: form.quantity, loss_category: form.event_type === 'GOOD' ? null : form.event_type === 'REWORK' ? 'APPROVED_REWORK' : form.loss_category, quantity_dimension: form.quantity_dimension, value_source: form.value_source, weight_uom_code: form.quantity_dimension === 'MASS' ? form.weight_uom_code : null, disposition_code: nullable(form.disposition_code)?.toUpperCase() ?? null, reason_code: form.event_type === 'GOOD' ? null : form.reason_code.trim().toUpperCase(), notes: nullable(form.notes) }, key.current); key.current = null; await refresh(selected.id); setForm(blankOutputClassification(form.weight_uom_code)); setFeedback({ error: null, success: 'Classified production output recorded and batch variance recalculated.', fields: {} }); } catch (error) { applyFailure(setFeedback, error, 'Unable to record production output.'); } finally { setBusy(false); }
  }
  async function resolve(id: string, disposition: string) { const notes = window.prompt(`${disposition === 'RECOVERED' ? 'Recovery' : 'Scrap'} resolution notes`); if (!notes?.trim()) return; setBusy(true); try { await resolveProductionRework(id, { disposition, notes: notes.trim() }, crypto.randomUUID()); await refresh(selected?.id); setFeedback({ error: null, success: `Rework ${disposition.toLowerCase()} and yield totals recalculated.`, fields: {} }); } catch (error) { applyFailure(setFeedback, error, 'Unable to resolve rework.'); } finally { setBusy(false); } }
  return <ManufacturingWorkspace code="PRO-LOSS" title="Yield / Loss / Rework" description="Compare expected and actual output while keeping process loss, handling waste, rejection, rework, giveaway, and unexplained variance distinct." notice="Count and physical-mass changes are recorded separately; quality release and rework disposition remain authoritative gates." loading={loading} feedback={feedback} workspace={workspace} search={search} setSearch={setSearch} status={status} setStatus={setStatus} sort={sort} setSort={setSort} page={page} setPage={setPage} headings={['Order / batch', 'Expected', 'Final good', 'Variance', 'Rework', 'Status']} rows={workspace?.data.map((row) => [<><b>{row.order_number}</b><small>{row.batch_number} · {row.calculation_model ?? 'LEGACY_YIELD'}</small></>, `${decimal(row.expected_good_quantity ?? row.planned_quantity)} ${row.uom_code}`, decimal(row.final_good_quantity ?? row.good_quantity), row.output_variance_percent === null ? row.output_variance_exception ?? 'n/a' : `${decimal(row.output_variance ?? '0')} · ${decimal(row.output_variance_percent ?? '0')}%`, <>{decimal(row.rework_quantity)}<small>{row.open_rework_count} open</small></>, <StatusBadge status={row.status} />]) ?? []} ids={workspace?.data.map((row) => row.id) ?? []} selectedId={selected?.id} onOpen={choose}>
    {selected ? <Detail><DetailHead status={selected.status} version={selected.record_version} /><div className="manufacturing-balance"><span>Expected good<b>{decimal(selected.expected_good_quantity ?? selected.planned_quantity)}</b></span><span>First pass good<b>{decimal(selected.first_pass_good_quantity ?? selected.good_quantity)}</b></span><span>Recovered rework<b>{decimal(selected.recovered_quantity ?? '0')}</b></span><span>Final good<b>{decimal(selected.final_good_quantity ?? selected.good_quantity)}</b></span><span>Variance<b>{decimal(selected.output_variance ?? '0')}</b></span></div><dl className="control-definition"><Datum text="Theoretical units / residual" value={`${decimal(selected.theoretical_complete_units ?? '0')} / ${decimal(selected.theoretical_residual_quantity ?? '0')}`} /><Datum text="Expected formed / good" value={`${decimal(selected.expected_formed_units ?? '0')} / ${decimal(selected.expected_good_quantity ?? '0')}`} /><Datum text="Normal process / handling" value={`${decimal(selected.normal_process_loss_quantity ?? '0')} / ${decimal(selected.handling_waste_quantity ?? '0')}`} /><Datum text="Rejected / unexplained" value={`${decimal(selected.rejected_output_quantity ?? '0')} / ${decimal(selected.unexplained_variance_quantity ?? '0')}`} /><Datum text="Overweight giveaway" value={decimal(selected.overweight_giveaway_quantity ?? '0')} /><Datum text="QC-approved good" value={decimal(selected.qc_approved_good_quantity ?? '0')} /></dl>{selected.allowed_actions.includes('RECORD_OUTPUT') ? <form className="requisition-form manufacturing-command" onSubmit={record}><fieldset disabled={busy}><div className="requisition-field-grid"><label>Output type<select aria-label="Output type" value={form.event_type} onChange={(e) => setForm({ ...form, event_type: e.target.value })}>{workspace?.lookups.event_types.map((type) => <option key={type}>{type}</option>)}</select></label><label>Quantity<input aria-label="Output quantity" type="number" min="0.000001" step="0.000001" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /><Field text={feedback.fields.quantity} /></label><label>Dimension<select aria-label="Output quantity dimension" value={form.quantity_dimension} onChange={(e) => setForm({ ...form, quantity_dimension: e.target.value })}>{workspace?.lookups.quantity_dimensions?.map((dimension) => <option key={dimension}>{dimension}</option>)}</select></label>{form.quantity_dimension === 'MASS' ? <label>Mass UOM<select aria-label="Output mass UOM" value={form.weight_uom_code} onChange={(e) => setForm({ ...form, weight_uom_code: e.target.value })}>{workspace?.lookups.uoms?.map((uom) => <option key={uom.code}>{uom.code}</option>)}</select></label> : null}<label>Reading source<select aria-label="Output value source" value={form.value_source} onChange={(e) => setForm({ ...form, value_source: e.target.value })}>{workspace?.lookups.value_sources?.map((source) => <option key={source}>{source}</option>)}</select></label>{form.event_type === 'LOSS' ? <label>Loss category<select aria-label="Loss category" value={form.loss_category} onChange={(e) => setForm({ ...form, loss_category: e.target.value, quantity_dimension: e.target.value === 'OVERWEIGHT_GIVEAWAY' ? 'MASS' : form.quantity_dimension })}>{workspace?.lookups.loss_categories?.filter((category) => category !== 'APPROVED_REWORK').map((category) => <option key={category}>{category}</option>)}</select></label> : null}{form.event_type !== 'GOOD' ? <label>Reason code<input aria-label="Reason code" value={form.reason_code} onChange={(e) => setForm({ ...form, reason_code: e.target.value })} /><Field text={feedback.fields.reason_code} /></label> : null}{form.loss_category === 'REJECTED_OUTPUT' && form.event_type === 'LOSS' ? <label>Disposition<input aria-label="Rejected output disposition" value={form.disposition_code} onChange={(e) => setForm({ ...form, disposition_code: e.target.value })} /><Field text={feedback.fields.disposition_code} /></label> : null}<label className="wide">Notes<textarea rows={2} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></label></div><div className="form-actions"><button className="primary" type="submit">Record classified output</button></div></fieldset></form> : null}<LineTable heads={['Seq', 'Type / classification', 'Quantity', 'Source / disposition', 'Recorded', 'Action']} rows={selected.outputs?.map((row) => [String(row.sequence_no), <><b>{row.event_type} · {row.loss_category ?? 'SALEABLE'}</b><small>{row.reason_code ?? 'No reason code'} · {row.quantity_dimension ?? 'COUNT'}</small></>, `${decimal(row.quantity)} ${row.uom_code}`, `${row.value_source ?? 'MEASURED'} / ${row.disposition_code ?? row.rework_status}`, dateTime(row.recorded_at), row.allowed_actions.includes('RESOLVE') ? <span className="table-actions"><button className="secondary compact-button" disabled={busy} onClick={() => void resolve(row.id, 'RECOVERED')}>Recover</button><button className="secondary compact-button" disabled={busy} onClick={() => void resolve(row.id, 'SCRAPPED')}>Scrap</button></span> : '—']) ?? []} /></Detail> : <Empty text="Choose an in-process or completed order to review yield." />}
  </ManufacturingWorkspace>;
}

function blankOrder() { return { order_number: '', batch_number: '', production_schedule_line_id: '', planned_start_date: '', planned_end_date: '', shift_code: '', notes: '' }; }
function blankAdjustment(uom_code = '') { return { adjustment_number: '', adjustment_type: 'OUTPUT', metric_code: 'GOOD_OUTPUT', subject_id: '', signed_quantity: '', uom_code, signed_value: '', reason: '' }; }
function blankMaterialDisposition() { return { parent_posting_id: '', disposition_kind: 'WASTE', quantity: '', reason_code: '', disposition_code: '', notes: '' }; }
function blankTemplateLine(uom = 'KG') { return { measurement_kind: 'INCOMING', quantity_dimension: 'MASS', uom_code: uom, is_required: true, default_value_source: 'MEASURED', measurement_method: '', balance_tolerance: '0' }; }
function blankMeasurement(line?: { measurement_kind: string; quantity_dimension: string; uom_code: string; default_value_source: string; measurement_method: string | null }) { return { measurement_kind: line?.measurement_kind ?? 'INCOMING', quantity_dimension: line?.quantity_dimension ?? 'MASS', quantity: '', uom_code: line?.uom_code ?? 'KG', value_source: line?.default_value_source ?? 'MEASURED', measurement_source: '', measurement_method: line?.measurement_method ?? '', target_quantity: '', reason_code: '', disposition_code: '', notes: '' }; }
function blankOutputClassification(weightUom = 'KG') { return { event_type: 'GOOD', quantity: '', loss_category: 'NORMAL_PROCESS_LOSS', quantity_dimension: 'COUNT', value_source: 'MEASURED', weight_uom_code: weightUom, disposition_code: '', reason_code: '', notes: '' }; }
function orderActionLabel(action: string) { return ({ RELEASE: 'Release order', ISSUE_MATERIALS: 'Issue reserved materials', COMPLETE: 'Complete order', CANCEL: 'Cancel order', QUALITY_RELEASE: 'Release quality' } as Record<string, string>)[action] ?? action; }
